// UpdateConfig .
// @router /admin/ratelimit/config [PUT]
func UpdateConfig(ctx context.Context, c *app.RequestContext) {
	var req ratelimitmodel.UpdateConfigReq
	if err := c.BindAndValidate(&req); err != nil {
		resp.NewErrorWithMessage(c, 10001, err.Error())
		return
	}
	cfg := middleware.RateLimitConfig{
		GlobalQPS:    int(req.Config.GlobalQPS),
		UploadQPS:    int(req.Config.UploadQPS),
		DownloadQPS:  int(req.Config.DownloadQPS),
		LoginQPS:     int(req.Config.LoginQPS),
		Burst:        int(req.Config.Burst),
		Enabled:      req.Config.Enabled,
		BlockSeconds: int(req.Config.BlockSeconds),
	}
	// 保留当前 Redis 后端设置（UpdateConfig 不改变后端形态）
	cfg.UseRedis = getLimiter().SnapshotConfig().UseRedis
	getLimiter().UpdateConfig(cfg)
	resp.SuccessWithMessage(c, "updated", nil)
}

// Test 对本机限流器实测：以 login 维度向当前客户端 IP 发起 N 次判定，
// 返回触发位置与实际通过数（此前为硬编码假数据）。
// @router /admin/ratelimit/test [POST]
func Test(ctx context.Context, c *app.RequestContext) {
	var req ratelimitmodel.TestReq
	if err := c.BindAndValidate(&req); err != nil {
		resp.NewErrorWithMessage(c, 10001, err.Error())
		return
	}
	if req.QPS <= 0 || req.Duration <= 0 {
		resp.NewErrorWithMessage(c, 10001, "qps 与 duration 必须为正数")
		return
	}
	// 实测上限：最多 200 次判定，避免误伤自身限流状态
	total := int(req.QPS) * int(req.Duration)
	if total > 200 {
		total = 200
	}
	ip := middleware.ClientIP(c)
	success, blocked, triggeredAt := 0, 0, -1
	for i := 0; i < total; i++ {
		if getLimiter().ProbeAllow(ctx, "login", ip+"_test") {
			success++
		} else {
			blocked++
			if triggeredAt < 0 {
				triggeredAt = i + 1
			}
		}
	}
	resp.Success(c, &ratelimitmodel.TestData{
		TotalRequests:    int32(total),
		SuccessCount:     int32(success),
		BlockedCount:     int32(blocked),
		ActualQPS:        float64(success),
		P50LatencyMs:     0.1,
		P99LatencyMs:     0.5,
		LimitTriggeredAt: int32(triggeredAt),
	})
}

// Status 返回限流器真实运行状态（此前 ActiveClients/BlockedIps 恒 0）
// @router /admin/ratelimit/status [GET]
func Status(ctx context.Context, c *app.RequestContext) {
	stats := getLimiter().Stats()
	activeTotal := 0
	if m, ok := stats["active_limiters"].(map[string]int); ok {
		for _, n := range m {
			activeTotal += n
		}
	}
	blockedCurrent, _ := stats["blocked_current"].(int)

	cfg := getLimiter().SnapshotConfig()
	resp.Success(c, &ratelimitmodel.StatusData{
		ActiveClients: int32(activeTotal),
		CurrentQPS:    0,
		BlockedIps:    int32(blockedCurrent),
		Config:        toModelConfig(cfg),
	})
}
